// Defensas 2 y 4 de la Fase 6: texto oculto (lector) y frases típicas de inyección (código).
// Además detecta si el correo pide un cambio de cuenta bancaria (lo resuelve A06, en el 8.4c).
const c = $('CA84a_Disparador').first().json;
const l = $input.first().json;
const FRASES = [
  /ignor[aá]\w*\s+(las|tus|todas\s+las)?\s*(instrucciones|reglas)/i,
  /instrucci[oó]n(es)?\s+para\s+el\s+sistema/i,
  /ya\s+fue\s+verificad[ao]/i,
  /apr[oó]b[aá]\w*\s+(para\s+)?(el\s+)?pago/i,
  /system\s+prompt|ignore\s+(all|previous)/i,
  /actualiz\w*\s+(el\s+)?cbu/i,
];
const todo = [l.texto || '', l.ocr || '', c.asunto || '', c.cuerpo || ''].join('\n');
const motivos = [...((l.texto_oculto && l.texto_oculto.motivos) || [])];
for (const f of FRASES) { const m = todo.match(f); if (m) motivos.push('Frase típica de inyección: "' + m[0] + '"'); }
const cbuCorreo = (String(c.cuerpo || '').match(/\b\d{22}\b/) || [null])[0];
const pideCambio = /(cambi\w*|nuev[ao])\s+(de\s+)?(banco|cuenta|cbu)/i.test(c.cuerpo || '');
return [{ json: {
  correo_id: c.correo_id, adjunto: c.adjunto, de: c.de, fecha_hora: c.fecha_hora, asunto: c.asunto,
  sospechoso: motivos.length > 0, motivo_seguridad: motivos.join('; ') || null,
  pide_cambio_cbu: pideCambio, cbu_en_correo: cbuCorreo, lectura: l,
} }];

// Tipo de documento por código: primero el QR de ARCA, después el texto u OCR.
const r = $input.first().json;
const q = r.lectura.qr && r.lectura.qr.datos;
// A: Responsable Inscripto. C: monotributista. La B no corresponde (Cumbre Andina es Responsable Inscripto): va a la cola.
const POR_QR = { 1: 'Factura A', 2: 'Nota de débito A', 3: 'Nota de crédito A', 11: 'Factura C', 12: 'Nota de débito C', 13: 'Nota de crédito C' };
let tipo = null, fuente = null;
if (q && POR_QR[q.tipoCmp]) { tipo = POR_QR[q.tipoCmp]; fuente = 'qr'; }
else {
  const t = ((r.lectura.texto || '') + '\n' + (r.lectura.ocr || '')).toUpperCase();
  const m = t.match(/\b(FACTURA|NOTA DE CR[EÉ]DITO|NOTA DE D[EÉ]BITO)\s*([ABC])\s*N/);
  if (m && (m[2] === 'A' || m[2] === 'C')) {
    tipo = (m[1] === 'FACTURA' ? 'Factura' : (m[1].includes('CR') ? 'Nota de crédito' : 'Nota de débito')) + ' ' + m[2];
    fuente = r.lectura.escaneado ? 'ocr' : 'texto';
  }
}
return [{ json: { tipo, fuente_tipo: fuente } }];

const r = $('CA84a_Seguridad').first().json;
return [{ json: { modo: 'texto', documento_id: r.adjunto, origen: 'facturas',
  texto: (r.lectura.texto || r.lectura.ocr || '').slice(0, 3000) } }];

// La IA solo elige de una lista cerrada. Cualquier otra respuesta se descarta (salida validada por código).
const TIPOS = ['Factura A', 'Nota de crédito A', 'Nota de débito A', 'Factura C', 'Nota de crédito C', 'Nota de débito C'];
const enm = $('CA84a_Enmascarar').first().json;
let tipo = null, motivo = null;
if (!enm.resuelto) motivo = 'No se clasificó: el enmascarado no fue seguro';
else {
  try {
    const resp = JSON.parse($input.first().json.response || '{}');
    if (TIPOS.includes(resp.tipo)) tipo = resp.tipo;
    else motivo = 'Tipo de documento no reconocido (la IA respondió: ' + (resp.tipo || 'nada') + ')';
  } catch (e) { motivo = 'Respuesta de la IA inválida'; }
}
return [{ json: { tipo, fuente_tipo: tipo ? 'ia' : null, motivo_tipo: motivo, modelo_ia: 'qwen3.5:9b' } }];

const s = $('CA84a_Seguridad').first().json;
let tipo = null, fuente = null, motivo = s.motivo_seguridad, modelo = null, estado;
if (s.sospechoso) estado = 'sospechoso';
else {
  const t = $('CA84a_Validar_IA').isExecuted ? $('CA84a_Validar_IA').first().json : $('CA84a_Tipo_por_codigo').first().json;
  tipo = t.tipo; fuente = t.fuente_tipo; modelo = t.modelo_ia || null;
  motivo = t.motivo_tipo || null;
  estado = tipo ? 'recibido' : 'a_la_cola';
}
return [{ json: { correo_id: s.correo_id, adjunto: s.adjunto, de: s.de, fecha_hora: s.fecha_hora,
  estado, tipo, fuente_tipo: fuente, motivo, modelo_ia: modelo,
  sigue_a_lectura: estado === 'recibido', pide_cambio_cbu: s.pide_cambio_cbu, cbu_en_correo: s.cbu_en_correo,
  lectura: s.lectura } }];

const r = $input.first().json;
return [{ json: { modo: 'fin', automatizacion_id: 'A04', documento_id: r.adjunto,
  estado: r.estado === 'sospechoso' ? 'bloqueado' : (r.estado === 'recibido' ? 'ok' : 'derivado_a_cola'),
  intervencion_humana: false, modelo_ia: r.modelo_ia || '', auditar: r.estado === 'sospechoso',
  actor: 'A04', accion: 'documento sospechoso', motivo: r.motivo || '' } }];
